import { useQueryClient } from '@tanstack/react-query';
import { Button } from '@ui/buttons/button';
import { Form } from '@ui/forms/form';
import { FormTextField } from '@ui/forms/input-field/text-field/text-field';
import { Trans } from '@ui/i18n/trans';
import { Dialog } from '@ui/overlays/dialog/dialog';
import { DialogBody } from '@ui/overlays/dialog/dialog-body';
import { useDialogContext } from '@ui/overlays/dialog/dialog-context';
import { DialogFooter } from '@ui/overlays/dialog/dialog-footer';
import { DialogHeader } from '@ui/overlays/dialog/dialog-header';
import { useForm } from 'react-hook-form';
import { ArtistPayoutMethod, useCreatePayoutMethod, useUpdatePayoutMethod } from './use-artist-payout-methods';

interface Props {
  method?: ArtistPayoutMethod;
}

export function PayoutMethodDialog({method}: Props) {
  const {formId, close} = useDialogContext();
  const queryClient = useQueryClient();
  const createMethod = useCreatePayoutMethod();
  const updateMethod = useUpdatePayoutMethod();

  interface FormValues {
    type: 'bank_transfer' | 'paypal' | 'stripe';
    account_holder_name: string;
    bank_name: string;
    iban: string;
    swift_code: string;
    account_number: string;
  }

  const form = useForm<FormValues>({
    defaultValues: method
      ? {
          type: method.type,
          account_holder_name: method.account_holder_name || '',
          bank_name: method.bank_name || '',
          iban: '',
          swift_code: method.swift_code || '',
          account_number: '',
        }
      : {
          type: 'bank_transfer',
          account_holder_name: '',
          bank_name: '',
          iban: '',
          swift_code: '',
          account_number: '',
        },
  });

  return (
    <Dialog size="lg">
      <DialogHeader>
        {method ? (
          <Trans message="Edit Bank Details" />
        ) : (
          <Trans message="Add Bank Details" />
        )}
      </DialogHeader>
      <DialogBody>
        <Form<FormValues>
          form={form}
          id={formId}
          onSubmit={async (values: FormValues) => {
            if (method) {
              await updateMethod.mutateAsync({
                id: method.id,
                ...values,
              });
            } else {
              await createMethod.mutateAsync({
                ...values,
                is_default: true,
              });
            }
            queryClient.invalidateQueries({queryKey: ['artists', 'payout-methods']});
            close();
          }}
        >
          <FormTextField
            autoFocus
            required
            name="account_holder_name"
            label={<Trans message="Account Holder Name" />}
            className="mb-16"
          />
          <FormTextField
            name="bank_name"
            label={<Trans message="Bank Name" />}
            className="mb-16"
          />
          <FormTextField
            required={!method}
            name="iban"
            label={<Trans message="IBAN" />}
            className="mb-16"
            placeholder={method ? "Leave blank to keep current value" : "GB82 WEST 1234 5698 7654 32"}
          />
          {method && (
            <p className="mb-16 text-xs text-muted">
              <Trans message="Leave blank to keep current IBAN" />
            </p>
          )}
          <FormTextField
            name="swift_code"
            label={<Trans message="BIC / SWIFT Code" />}
            className="mb-16"
            placeholder="CHASUS33"
          />
          <FormTextField
            name="account_number"
            label={<Trans message="Account Number" />}
            className="mb-16"
            placeholder={method ? "Leave blank to keep current value" : undefined}
          />
          {method && (
            <p className="mb-16 text-xs text-muted">
              <Trans message="Leave blank to keep current account number" />
            </p>
          )}
        </Form>
      </DialogBody>
      <DialogFooter>
        <Button onClick={() => close()}>
          <Trans message="Cancel" />
        </Button>
        <Button
          type="submit"
          form={formId}
          variant="flat"
          color="primary"
          disabled={createMethod.isPending || updateMethod.isPending}
        >
          {method ? <Trans message="Update" /> : <Trans message="Add" />}
        </Button>
      </DialogFooter>
    </Dialog>
  );
}
