import {
  useMutation,
  useQuery,
  useQueryClient,
} from '@tanstack/react-query';
import {apiClient} from '@common/http/query-client';
import {toast} from '@ui/toast/toast';
import {BackendResponse} from '@common/http/backend-response/backend-response';
import {useTrans} from '@ui/i18n/use-trans';
import {message} from '@ui/i18n/message';

export interface ArtistPayoutMethod {
  id: number;
  artist_id: number;
  type: 'bank_transfer' | 'paypal' | 'stripe';
  account_holder_name?: string;
  bank_name?: string;
  account_number?: string;
  iban?: string;
  swift_code?: string;
  paypal_email?: string;
  stripe_account_id?: string;
  is_default: boolean;
  is_verified: boolean;
  masked_account?: string;
  masked_iban?: string;
  masked_account_number?: string;
  created_at: string;
  updated_at: string;
}

interface PayoutMethodsResponse extends BackendResponse {
  methods: ArtistPayoutMethod[];
}

const PAYOUT_METHODS_KEY = ['artists', 'payout-methods'];

export function useArtistPayoutMethods() {
  return useQuery({
    queryKey: PAYOUT_METHODS_KEY,
    queryFn: () => fetchPayoutMethods(),
    retry: false,
    throwOnError: false,
  });
}

function fetchPayoutMethods(): Promise<PayoutMethodsResponse> {
  return apiClient
    .get('artists/payout-methods')
    .then(response => response.data);
}

interface CreatePayoutMethodPayload {
  type: 'bank_transfer' | 'paypal' | 'stripe';
  account_holder_name?: string;
  bank_name?: string;
  account_number?: string;
  iban?: string;
  swift_code?: string;
  paypal_email?: string;
  stripe_account_id?: string;
  is_default?: boolean;
}

export function useCreatePayoutMethod() {
  const {trans} = useTrans();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (payload: CreatePayoutMethodPayload) =>
      createPayoutMethod(payload),
    onSuccess: () => {
      toast(trans(message('Payment method added successfully')));
      queryClient.invalidateQueries({queryKey: PAYOUT_METHODS_KEY});
    },
    onError: (err: any) =>
      toast.danger(
        err.response?.data?.message ||
          trans(message('Could not add payment method')),
      ),
  });
}

function createPayoutMethod(payload: CreatePayoutMethodPayload) {
  return apiClient
    .post('artists/payout-methods', payload)
    .then(r => r.data);
}

interface UpdatePayoutMethodPayload extends CreatePayoutMethodPayload {
  id: number;
}

export function useUpdatePayoutMethod() {
  const {trans} = useTrans();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (payload: UpdatePayoutMethodPayload) =>
      updatePayoutMethod(payload),
    onSuccess: () => {
      toast(trans(message('Payment method updated successfully')));
      queryClient.invalidateQueries({queryKey: PAYOUT_METHODS_KEY});
    },
    onError: (err: any) =>
      toast.danger(
        err.response?.data?.message ||
          trans(message('Could not update payment method')),
      ),
  });
}

function updatePayoutMethod({id, ...payload}: UpdatePayoutMethodPayload) {
  return apiClient
    .put(`artists/payout-methods/${id}`, payload)
    .then(r => r.data);
}

export function useDeletePayoutMethod() {
  const {trans} = useTrans();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (id: number) => deletePayoutMethod(id),
    onSuccess: () => {
      toast(trans(message('Payment method deleted successfully')));
      queryClient.invalidateQueries({queryKey: PAYOUT_METHODS_KEY});
    },
    onError: (err: any) =>
      toast.danger(
        err.response?.data?.message ||
          trans(message('Could not delete payment method')),
      ),
  });
}

function deletePayoutMethod(id: number) {
  return apiClient.delete(`artists/payout-methods/${id}`).then(r => r.data);
}
