import { apiClient } from '@common/http/query-client';
import { useQuery } from '@tanstack/react-query';
import { DateRangeValue } from '@ui/forms/input-field/date/date-range-picker/date-range-value';

interface ArtistEarning {
  id: number;
  artist_id: number;
  earning_date: string;
  followers_count: number;
  gross_amount: number;
  platform_fee: number;
  net_amount: number;
  status: 'pending' | 'accrued' | 'paid';
  created_at: string;
  updated_at: string;
}

interface EarningSummary {
  gross: number;
  fee: number;
  net: number;
}

interface MonthlyEarning {
  period?: string;
  year: number;
  month: number;
  gross_amount: number;
  platform_fee: number;
  net_amount: number;
  followers_count?: number;
  avg_followers: number;
  status: 'pending' | 'accrued' | 'paid' | 'requested' | 'rejected';
}

interface EstimatedEarnings {
  period: string;
  followers_count: number;
  gross_amount: number;
  platform_fee: number;
  net_amount: number;
  accrual_date: string;
}

interface ArtistEarningsResponse {
  summary: {
    total_earnings: EarningSummary;
    pending_earnings: EarningSummary;
    accrued_earnings: EarningSummary;
    paid_earnings: EarningSummary;
    paid_this_month: EarningSummary;
  };
  daily_earnings: ArtistEarning[];
  monthly_earnings: MonthlyEarning[];
  current_followers: number;
  estimated_earnings?: EstimatedEarnings | null;
}

interface Params {
  dateRange?: DateRangeValue;
}

export function useArtistEarnings(params: Params = {}) {
  return useQuery({
    queryKey: ['artist-earnings', params],
    queryFn: () => fetchArtistEarnings(params),
    retry: false,
    throwOnError: false,
  });
}

function fetchArtistEarnings(params: Params) {
  const queryParams: Record<string, string> = {};

  if (params.dateRange) {
    queryParams.startDate = params.dateRange.start.toAbsoluteString();
    queryParams.endDate = params.dateRange.end.toAbsoluteString();
  }

  return apiClient
    .get<ArtistEarningsResponse>('artists/earnings', {
      params: queryParams,
    })
    .then(response => response.data);
}
