import { Button } from '@ui/buttons/button';
import { Chip } from '@ui/forms/input-field/chip-field/chip';
import { FormattedCurrency } from '@ui/i18n/formatted-currency';
import { FormattedDate } from '@ui/i18n/formatted-date';
import { FormattedNumber } from '@ui/i18n/formatted-number';
import { Trans } from '@ui/i18n/trans';
import { AccountBalanceIcon } from '@ui/icons/material/AccountBalance';
import { AddIcon } from '@ui/icons/material/Add';
import { AttachMoneyIcon } from '@ui/icons/material/AttachMoney';
import { CalendarTodayIcon } from '@ui/icons/material/CalendarToday';
import { PeopleIcon } from '@ui/icons/material/People';
import { TrendingUpIcon } from '@ui/icons/material/TrendingUp';
import { DialogTrigger } from '@ui/overlays/dialog/dialog-trigger';
import { ProgressCircle } from '@ui/progress/progress-circle';
import { useMemo } from 'react';
import { PayoutMethodDialog } from './payout-method-dialog';
import { useArtistEarnings } from './use-artist-earnings';
import { useArtistPayoutMethods } from './use-artist-payout-methods';
import { useCreatePayout } from './use-artist-payouts';

export function Component() {
  const {data, isPending, error} = useArtistEarnings({});
  const {data: payoutMethodsData, error: payoutMethodsError} = useArtistPayoutMethods();
  const createPayout = useCreatePayout();

  const summary = data?.summary;
  const monthlyEarningsRaw = data?.monthly_earnings || [];
  const currentFollowers = data?.current_followers || 0;
  const estimatedEarnings = data?.estimated_earnings;
  const payoutMethods = payoutMethodsData?.methods || [];
  const defaultPayoutMethod = payoutMethods.find(m => m.is_default) || payoutMethods[0];
  const displayPayoutMethod = defaultPayoutMethod;

  // Group earnings by period, showing the highest priority status
  // Priority: paid > requested > accrued > pending > rejected
  const monthlyEarnings = useMemo(() => {
    const grouped = monthlyEarningsRaw.reduce((acc, earning) => {
      const key = earning.period || `${earning.year}-${String(earning.month).padStart(2, '0')}`;
      if (!acc[key]) {
        acc[key] = {
          period: earning.period,
          year: earning.year,
          month: earning.month,
          gross_amount: 0,
          platform_fee: 0,
          net_amount: 0,
          followers_count: earning.followers_count || earning.avg_followers || 0,
          avg_followers: earning.followers_count || earning.avg_followers || 0,
          status: earning.status,
        };
      }
      acc[key].gross_amount += earning.gross_amount;
      acc[key].platform_fee += earning.platform_fee;
      acc[key].net_amount += earning.net_amount;
      acc[key].followers_count = Math.max(acc[key].followers_count, earning.followers_count || earning.avg_followers || 0);
      acc[key].avg_followers = acc[key].followers_count;

      // Status priority: paid > accrued > pending > rejected
      const statusPriority = {paid: 4, accrued: 3, pending: 2, rejected: 1};
      const currentPriority = statusPriority[acc[key].status as keyof typeof statusPriority] || 0;
      const newPriority = statusPriority[earning.status as keyof typeof statusPriority] || 0;
      if (newPriority > currentPriority) {
        acc[key].status = earning.status;
      }
      return acc;
    }, {} as Record<string, any>);

    // Add estimated earnings if it exists and not already in the list
    if (estimatedEarnings) {
      const estKey = estimatedEarnings.period;
      if (!grouped[estKey]) {
        const periodParts = estimatedEarnings.period.split('-');
        grouped[estKey] = {
          period: estimatedEarnings.period,
          year: parseInt(periodParts[0]),
          month: parseInt(periodParts[1]),
          gross_amount: estimatedEarnings.gross_amount,
          platform_fee: estimatedEarnings.platform_fee,
          net_amount: estimatedEarnings.net_amount,
          followers_count: estimatedEarnings.followers_count,
          avg_followers: estimatedEarnings.followers_count,
          status: 'estimated' as const,
          isEstimated: true,
        };
      }
    }

    return Object.values(grouped).sort((a: any, b: any) => {
      if (a.period && b.period) {
        return b.period.localeCompare(a.period);
      }
      if (a.year !== b.year) return b.year - a.year;
      return b.month - a.month;
    });
  }, [monthlyEarningsRaw, estimatedEarnings]);

  // Next payout date = when next month's earnings will accrue (5th of next month)
  // This shows when the previous month's earnings become available
  const nextPayoutDate = useMemo(() => {
    const now = new Date();
    const currentDay = now.getDate();

    // If before 5th, next accrual is 5th of this month
    // If after 5th, next accrual is 5th of next month
    if (currentDay < 5) {
      return new Date(now.getFullYear(), now.getMonth(), 5);
    } else {
      return new Date(now.getFullYear(), now.getMonth() + 1, 5);
    }
  }, []);

  if (isPending) {
    return (
      <div className="flex h-400 items-center justify-center">
        <ProgressCircle isIndeterminate />
      </div>
    );
  }

  if (error || payoutMethodsError) {
    const errorMessage = (error as any)?.response?.data?.message ||
                        (payoutMethodsError as any)?.response?.data?.message ||
                        'No artist profile found. Please create an artist profile first.';
    return (
      <div>
        <div className="rounded-panel border p-24 text-center">
          <h2 className="mb-8 text-xl font-semibold">
            <Trans message="No Artist Profile" />
          </h2>
          <p className="text-muted">
            <Trans message={errorMessage} />
          </p>
        </div>
      </div>
    );
  }

  const accruedAmount = (summary?.accrued_earnings.net || 0) / 100;
  const pendingAmount = (summary?.pending_earnings.net || 0) / 100;
  const paidThisMonth = (summary?.paid_this_month?.net || 0) / 100;

  // Available earnings should ONLY be accrued (pending is analytics only, not payable)
  const availableEarnings = accruedAmount;

  const handleRequestPayout = () => {
    if (!displayPayoutMethod) {
      return;
    }
    createPayout.mutate({
      payout_method_id: displayPayoutMethod.id,
      amount: Math.round(accruedAmount * 100),
    });
  };

  return (
    <div>
      <div className="mb-24">
        <h1 className="mb-4 text-3xl font-semibold">
          <Trans message="My Earnings" />
        </h1>
        <p className="text-sm text-muted">
          <Trans message="Track your revenue and manage payouts" />
        </p>
      </div>

      <div className="mb-32 grid gap-16 md:grid-cols-2 lg:grid-cols-5">
        <SummaryCard
          title={<Trans message="Total Followers" />}
          value={<FormattedNumber value={currentFollowers} />}
          icon={<PeopleIcon />}
        />
        <SummaryCard
          title={<Trans message="Available Earnings" />}
          value={
            <FormattedCurrency
              value={availableEarnings}
              currency="USD"
            />
          }
          icon={<AccountBalanceIcon />}
          subtitle={
            estimatedEarnings && availableEarnings === 0 ? (
              <span>
                <Trans message="Est. :amount on :date" values={{
                  amount: <FormattedCurrency value={estimatedEarnings.net_amount / 100} currency="USD" />,
                  date: new Date(estimatedEarnings.accrual_date).toLocaleDateString('en-US', {month: 'short', day: 'numeric'})
                }} />
              </span>
            ) : (
              <Trans message="Accrued (payable)" />
            )
          }
        />
        <SummaryCard
          title={<Trans message="Paid This Month" />}
          value={<FormattedCurrency value={paidThisMonth} currency="USD" />}
          icon={<AttachMoneyIcon />}
        />
        <SummaryCard
          title={<Trans message="Next Payout Date" />}
          value={<FormattedDate date={nextPayoutDate} />}
          icon={<CalendarTodayIcon />}
        />
        <SummaryCard
          title={<Trans message="Revenue Per Follower" />}
          value={<FormattedCurrency value={0.1} currency="USD" />}
          subtitle={<Trans message="/ month" />}
          icon={<TrendingUpIcon />}
        />
      </div>

      <div className="mb-32 grid gap-24 md:grid-cols-2">
        <div className="rounded-panel border">
          <div className="border-b p-16">
            <h2 className="text-xl font-semibold">
              <Trans message="Monthly Earnings" />
            </h2>
          </div>
          <div className="p-16">
            {estimatedEarnings && monthlyEarnings.length === 0 && (
              <div className="mb-16 rounded border border-primary/20 bg-primary/5 p-16">
                <div className="mb-8 text-sm font-medium text-primary">
                  <Trans message="Upcoming Accrual" />
                </div>
                <div className="text-xs text-muted mb-8">
                  <Trans message="Period: :period • Accrues: :date" values={{
                    period: estimatedEarnings.period,
                    date: new Date(estimatedEarnings.accrual_date).toLocaleDateString('en-US', {month: 'long', day: 'numeric', year: 'numeric'})
                  }} />
                </div>
                <div className="text-lg font-semibold">
                  <FormattedCurrency value={estimatedEarnings.net_amount / 100} currency="USD" />
                </div>
                <div className="mt-4 text-xs text-muted">
                  <Trans message="Based on :count follower(s) at period end" values={{
                    count: estimatedEarnings.followers_count
                  }} />
                </div>
              </div>
            )}
            <MonthlyEarningsChart earnings={monthlyEarnings} />
          </div>
        </div>

        <div className="rounded-panel border">
          <div className="border-b p-16">
            <h2 className="text-xl font-semibold">
              <Trans message="Earnings History" />
            </h2>
            <p className="mt-4 text-xs text-muted">
              <Trans message="Accrued amounts reflect followers at that period's end; current followers affect the next accrual only." />
            </p>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead>
                <tr className="border-b bg-alt text-left text-xs font-medium uppercase text-muted">
                  <th className="p-12">
                    <Trans message="Period" />
                  </th>
                  <th className="p-12">
                    <Trans message="Followers" />
                  </th>
                  <th className="p-12">
                    <Trans message="Amount" />
                  </th>
                  <th className="p-12">
                    <Trans message="Status" />
                  </th>
                </tr>
              </thead>
              <tbody>
                {monthlyEarnings.length === 0 ? (
                  <tr>
                    <td colSpan={4} className="p-24 text-center text-muted">
                      <Trans message="No earnings data available" />
                    </td>
                  </tr>
                ) : (
                  monthlyEarnings.map((earning: any, index) => (
                    <tr key={earning.period || index} className="border-b hover:bg-hover">
                      <td className="p-12">
                        {earning.period ? (
                          <span className="font-medium">{earning.period}</span>
                        ) : (
                          new Date(earning.year, earning.month - 1).toLocaleDateString(
                            'en-US',
                            {year: 'numeric', month: 'short'},
                          )
                        )}
                      </td>
                      <td className="p-12">
                        <FormattedNumber value={Math.round(earning.followers_count || earning.avg_followers || 0)} />
                      </td>
                      <td className="p-12 font-medium">
                        <FormattedCurrency
                          value={(earning.net_amount || 0) / 100}
                          currency="USD"
                        />
                      </td>
                      <td className="p-12">
                        {earning.isEstimated ? (
                          <Chip color="primary" size="sm">
                            <Trans message="Estimated (accrues :date)" values={{
                              date: estimatedEarnings ? new Date(estimatedEarnings.accrual_date).toLocaleDateString('en-US', {month: 'short', day: 'numeric'}) : ''
                            }} />
                          </Chip>
                        ) : (
                          <StatusBadge status={earning.status || 'pending'} />
                        )}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      <div className="grid gap-24 md:grid-cols-2">
        <div className="rounded-panel border">
          <div className="border-b p-16">
            <h2 className="flex items-center gap-8 text-xl font-semibold">
              <AccountBalanceIcon size="sm" />
              <Trans message="Bank Transfer & Payouts" />
            </h2>
          </div>
          <div className="p-16">
            <div className="mb-12 flex items-center justify-between">
              <h3 className="text-sm font-medium">
                <Trans message="Bank Transfer Details" />
              </h3>
              <DialogTrigger type="modal">
                <Button
                  variant="outline"
                  color="primary"
                  size="xs"
                  startIcon={<AddIcon />}
                >
                  {displayPayoutMethod ? (
                    <Trans message="Update Bank Details" />
                  ) : (
                    <Trans message="Add Bank Details" />
                  )}
                </Button>
                <PayoutMethodDialog method={displayPayoutMethod} />
              </DialogTrigger>
            </div>
            {displayPayoutMethod ? (
              <div className="space-y-8 text-sm">
                {displayPayoutMethod.account_holder_name && (
                  <div>
                    <span className="text-muted">
                      <Trans message="Account Holder:" />
                    </span>{' '}
                    <span className="font-medium">
                      {displayPayoutMethod.account_holder_name}
                    </span>
                  </div>
                )}
                {displayPayoutMethod.masked_iban && (
                  <div>
                    <span className="text-muted">
                      <Trans message="IBAN:" />
                    </span>{' '}
                    <span className="font-medium">{displayPayoutMethod.masked_iban}</span>
                  </div>
                )}
                {displayPayoutMethod.swift_code && (
                  <div>
                    <span className="text-muted">
                      <Trans message="BIC:" />
                    </span>{' '}
                    <span className="font-medium">{displayPayoutMethod.swift_code}</span>
                  </div>
                )}
                {displayPayoutMethod.masked_account_number && (
                  <div>
                    <span className="text-muted">
                      <Trans message="Account Number:" />
                    </span>{' '}
                    <span className="font-medium">{displayPayoutMethod.masked_account_number}</span>
                  </div>
                )}
              </div>
            ) : (
              <p className="text-sm text-muted">
                <Trans message="No bank details configured" />
              </p>
            )}
          </div>
        </div>

        <div className="rounded-panel border">
          <div className="border-b p-16">
            <h2 className="text-xl font-semibold">
              <Trans message="Payout Options" />
            </h2>
          </div>
          <div className="p-16">
            <div className="mb-16">
              <div className="mb-4 text-sm text-muted">
                <Trans message="Available to Withdraw:" />
              </div>
              <div className="text-2xl font-bold">
                <FormattedCurrency value={accruedAmount} currency="USD" />
              </div>
              {estimatedEarnings && (
                <p className="mt-8 text-xs text-muted">
                  <Trans message="Next accrual: :amount on :date (:followers followers)" values={{
                    amount: <FormattedCurrency value={estimatedEarnings.net_amount / 100} currency="USD" />,
                    date: new Date(estimatedEarnings.accrual_date).toLocaleDateString('en-US', {month: 'short', day: 'numeric'}),
                    followers: estimatedEarnings.followers_count
                  }} />
                </p>
              )}
              {pendingAmount > 0 && (
                <p className="mt-8 text-xs text-muted">
                  <Trans message=":amount in pending earnings (analytics only, not payable)" values={{
                    amount: <FormattedCurrency value={pendingAmount} currency="USD" />
                  }} />
                </p>
              )}
              {accruedAmount === 0 && pendingAmount === 0 && !estimatedEarnings && (
                <p className="mt-8 text-xs text-muted">
                  <Trans message="Earnings accrue monthly on the 5th of each month for the previous month's followers." />
                </p>
              )}
            </div>
            <p className="mb-16 text-xs text-muted">
              <Trans message="Platform fee: 10% (already deducted)" />
            </p>
            <Button
              variant="flat"
              color="primary"
              onClick={handleRequestPayout}
              disabled={!displayPayoutMethod || accruedAmount < 10 || createPayout.isPending}
            >
              <Trans message="Request Payout" />
            </Button>
            {!displayPayoutMethod && (
              <p className="mt-8 text-xs text-muted">
                <Trans message="Please add bank details to request a payout" />
              </p>
            )}
            {displayPayoutMethod && accruedAmount < 10 && (
              <p className="mt-8 text-xs text-muted">
                <Trans message="Minimum payout is $10." />
              </p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

interface SummaryCardProps {
  title: React.ReactNode;
  value: React.ReactNode;
  subtitle?: React.ReactNode;
  icon?: React.ReactNode;
}

function SummaryCard({title, value, subtitle, icon}: SummaryCardProps) {
  return (
    <div className="rounded-panel p-20">
      <div className="mb-8 flex items-center justify-between">
        <div className="text-xs font-medium uppercase text-muted">{title}</div>
        {icon && <div className="text-muted">{icon}</div>}
      </div>
      <div className="mb-4 text-2xl font-bold">{value}</div>
      {subtitle && <div className="text-sm text-muted">{subtitle}</div>}
    </div>
  );
}

interface MonthlyEarningsChartProps {
  earnings: Array<{
    period?: string;
    year: number;
    month: number;
    gross_amount: number;
    platform_fee: number;
    net_amount: number;
    status: 'pending' | 'accrued' | 'paid' | 'rejected';
  }>;
}

function MonthlyEarningsChart({earnings}: MonthlyEarningsChartProps) {
  // Filter out estimated earnings from chart (they're shown separately)
  const chartEarnings = earnings.filter((e: any) => !e.isEstimated);

  if (chartEarnings.length === 0) {
    return (
      <div className="flex h-200 items-center justify-center text-muted">
        <Trans message="No data available. Earnings will appear after accrual." />
      </div>
    );
  }

  const maxAmount = Math.max(
    ...chartEarnings.map(e => e.net_amount),
    0,
  );

  const chartHeight = 200;
  const minBarHeightPx = 8;
  const minBarHeightPercent = (minBarHeightPx / chartHeight) * 100;

  const getYAxisMax = (max: number) => {
    if (max === 0) return 10;
    const rounded = Math.ceil(max * 1.2);
    if (rounded < 100) return Math.max(10, Math.ceil(rounded / 10) * 10);
    if (rounded < 1000) return Math.ceil(rounded / 100) * 100;
    if (rounded < 10000) return Math.ceil(rounded / 1000) * 1000;
    return Math.ceil(rounded / 10000) * 10000;
  };

  const yAxisMax = getYAxisMax(maxAmount);
  const yAxisSteps = 5;
  const yAxisValues = Array.from({length: yAxisSteps + 1}, (_, i) => {
    return (yAxisMax / yAxisSteps) * i;
  }).reverse();

  return (
    <div className="space-y-16">
      <div className="flex gap-12">
        <div className="flex h-200 flex-col justify-between pb-8 text-xs text-muted">
          {yAxisValues.map((value, index) => (
            <div key={index} className="h-40 flex items-end justify-end">
              <span className="whitespace-nowrap">
                <FormattedCurrency value={value / 100} currency="USD" />
              </span>
            </div>
          ))}
        </div>
        <div className="flex-1">
          <div className="flex h-200 items-end gap-8">
            {chartEarnings.map((earning: any, index) => {
              const amount = earning.net_amount || 0;
              const calculatedHeight = yAxisMax > 0 ? (amount / yAxisMax) * 100 : 0;
              const height = Math.max(calculatedHeight, minBarHeightPercent);
              const color =
                earning.status === 'paid'
                  ? 'bg-positive'
                  : earning.status === 'accrued'
                    ? 'bg-primary'
                    : earning.status === 'rejected'
                      ? 'bg-danger'
                      : 'bg-warning';

              return (
                <div key={index} className="flex flex-1 flex-col items-center gap-4">
                  <div className="relative flex h-full w-full items-end justify-center">
                    <div
                      className={`w-full ${color} rounded-t transition-all opacity-90 hover:opacity-100`}
                      style={{
                        height: `${height}%`,
                        minHeight: `${minBarHeightPx}px`,
                      }}
                      title={`$${(amount / 100).toFixed(2)}`}
                    />
                  </div>
                  <div className="text-xs text-muted">
                    {new Date(earning.year, earning.month - 1).toLocaleDateString(
                      'en-US',
                      {month: 'short'},
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
      <div className="flex items-center justify-center gap-16 text-xs">
        <div className="flex items-center gap-4">
          <div className="h-12 w-12 rounded bg-positive" />
          <span className="text-muted">
            <Trans message="Paid" />
          </span>
        </div>
        <div className="flex items-center gap-4">
          <div className="h-12 w-12 rounded bg-primary" />
          <span className="text-muted">
            <Trans message="Accrued" />
          </span>
        </div>
        <div className="flex items-center gap-4">
          <div className="h-12 w-12 rounded bg-warning" />
          <span className="text-muted">
            <Trans message="Pending" />
          </span>
        </div>
        <div className="flex items-center gap-4">
          <div className="h-12 w-12 rounded bg-danger" />
          <span className="text-muted">
            <Trans message="Rejected" />
          </span>
        </div>
      </div>
    </div>
  );
}

interface StatusBadgeProps {
  status: 'pending' | 'accrued' | 'paid' | 'rejected';
}

function StatusBadge({status}: StatusBadgeProps) {
  const labels = {
    pending: <Trans message="Pending (Analytics)" />,
    accrued: <Trans message="Accrued" />,
    paid: <Trans message="Paid" />,
    rejected: <Trans message="Rejected" />,
  };

  const chipColors = {
    pending: 'warning',
    accrued: 'primary',
    paid: 'success',
    rejected: 'danger',
  } as const;

  return (
    <Chip color={chipColors[status] || 'chip'} size="sm">
      {labels[status] || status}
    </Chip>
  );
}
