import {
  useMutation,
  useQuery,
  useQueryClient,
} from '@tanstack/react-query';
import {apiClient} from '@common/http/query-client';
import {toast} from '@ui/toast/toast';
import {BackendResponse} from '@common/http/backend-response/backend-response';
import {useTrans} from '@ui/i18n/use-trans';
import {message} from '@ui/i18n/message';
import {ArtistPayoutMethod} from './use-artist-payout-methods';

export interface ArtistPayout {
  id: number;
  artist_id: number;
  period?: string;
  payout_method_id: number;
  amount: number;
  status: 'pending' | 'approved' | 'processing' | 'completed' | 'rejected' | 'failed';
  requested_at: string;
  approved_at?: string;
  approved_by?: number;
  completed_at?: string;
  rejected_at?: string;
  rejection_reason?: string;
  admin_notes?: string;
  created_at: string;
  updated_at: string;
  payout_method?: ArtistPayoutMethod;
  artist?: {
    id: number;
    name: string;
    user_email?: string;
  };
  followers_count?: number;
  total_accrued_earnings?: number;
  total_accrued_gross?: number;
  total_accrued_fee?: number;
  period_earnings?: number;
  period_gross?: number;
  period_fee?: number;
}

interface PayoutsResponse extends BackendResponse {
  payouts: {
    data: ArtistPayout[];
    current_page: number;
    per_page: number;
    total: number;
  };
}

const PAYOUTS_KEY = ['artists', 'payouts'];

export function useArtistPayouts() {
  return useQuery({
    queryKey: PAYOUTS_KEY,
    queryFn: () => fetchPayouts(),
  });
}

function fetchPayouts(): Promise<PayoutsResponse> {
  return apiClient.get('artists/payouts').then(response => response.data);
}

interface CreatePayoutPayload {
  payout_method_id: number;
  amount: number;
}

export function useCreatePayout() {
  const {trans} = useTrans();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (payload: CreatePayoutPayload) => createPayout(payload),
    onSuccess: () => {
      toast(trans(message('Payout request submitted successfully')));
      queryClient.invalidateQueries({queryKey: PAYOUTS_KEY});
      queryClient.invalidateQueries({queryKey: ['artists', 'earnings']});
    },
    onError: (err: any) =>
      toast.danger(
        err.response?.data?.message ||
          trans(message('Could not submit payout request')),
      ),
  });
}

function createPayout(payload: CreatePayoutPayload) {
  return apiClient.post('artists/payouts', payload).then(r => r.data);
}

export function useCancelPayout() {
  const {trans} = useTrans();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (id: number) => cancelPayout(id),
    onSuccess: () => {
      toast(trans(message('Payout request cancelled successfully')));
      queryClient.invalidateQueries({queryKey: PAYOUTS_KEY});
      queryClient.invalidateQueries({queryKey: ['artists', 'earnings']});
    },
    onError: (err: any) =>
      toast.danger(
        err.response?.data?.message ||
          trans(message('Could not cancel payout request')),
      ),
  });
}

function cancelPayout(id: number) {
  return apiClient.post(`artists/payouts/${id}/cancel`).then(r => r.data);
}
